#include <vector>
#include <array>
#include <cstddef>
#include <omp.h>

struct Point {
   double x, y;
};

void countQuadrants(std::vector<Point> const& points, std::array<size_t, 4> &bins) {
    bins = {0u, 0u, 0u, 0u};

    int nthreads = 1;
    #pragma omp parallel
    {
        #pragma omp single
        nthreads = omp_get_num_threads();
    }

    // Per-thread private bins to avoid races; then merge safely.
    std::vector<std::array<size_t, 4>> local(static_cast<size_t>(nthreads),
                                             std::array<size_t, 4>{0u, 0u, 0u, 0u});

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        auto &lb = local[static_cast<size_t>(tid)];

        #pragma omp for schedule(static)
        for (std::size_t i = 0; i < points.size(); ++i) {
            const double x = points[i].x;
            const double y = points[i].y;

            // Define quadrants with axis points included:
            // Q0: x>=0, y>=0; Q1: x<0, y>=0; Q2: x<0, y<0; Q3: x>=0, y<0
            const std::size_t q =
                (y >= 0.0)
                    ? ((x >= 0.0) ? 0u : 1u)
                    : ((x >= 0.0) ? 3u : 2u);

            ++lb[q];
        }

        #pragma omp barrier

        #pragma omp for schedule(static)
        for (int t = 0; t < nthreads; ++t) {
            // Each iteration writes a unique local[t], but accumulation goes to shared bins.
            // Use atomics for each bin update.
            for (int b = 0; b < 4; ++b) {
                const size_t val = local[static_cast<size_t>(t)][static_cast<size_t>(b)];
                if (val) {
                    #pragma omp atomic update
                    bins[static_cast<size_t>(b)] += val;
                }
            }
        }
    }
}
